// The generated Next handler serves pages; research APIs avoid its request CPU overhead.
// @ts-ignore Generated by the isolated OpenNext build.
import nextWorker from '../.open-next/worker.js';
// @ts-ignore Generated by OpenNext; also establishes runtime-only secret bindings.
import { runWithCloudflareRequestContext } from '../.open-next/cloudflare/init.js';
import { researchJobHttp } from '../src/lib/hosting/job-http';
import type { JobEnvironment } from '../src/lib/hosting/job-store';
import { failInterruptedJob, queueSignature, validJobId, validQueueSignature } from '../src/lib/hosting/job-store';

// SQLite-backed Durable Objects are available on Workers Free. Each job gets
// its own execution context and 30 seconds of active CPU, separate from the
// Free queue consumer's much smaller runtime allowance. Network wait is I/O.
export class ResearchRunner {
    constructor(private state: unknown, private env: JobEnvironment) {}
    async fetch(request: Request) {
        return runWithCloudflareRequestContext(request, this.env, this.state, async () => {
            const id=request.headers.get('X-Research-Job')||'',time=Number(request.headers.get('X-Research-Time'));
            if(request.method!=='POST'||new URL(request.url).pathname!=='/api/internal/research-job'||!validQueueSignature(id,time,request.headers.get('X-Research-Signature')||''))
                return new Response(null,{status:404});
            // Reuse the generated server bundle: a second research/PDF bundle
            // would exceed the Free plan's script upload size.
            return nextWorker.fetch(request,this.env,this.state);
        });
    }
}
export default {
    async fetch(request: Request, env: JobEnvironment, ctx: unknown) {
        const path = new URL(request.url).pathname;
        if(path==='/api/internal/research-job')return new Response('Not found',{status:404});
        if (['/api/status', '/api/guest/session', '/api/guest/research', '/api/research'].includes(path) || /^\/api\/(?:guest\/research|research)\/jobs\//.test(path))
            return runWithCloudflareRequestContext(request, env, ctx, () => researchJobHttp(request, env));
        return nextWorker.fetch(request, env, ctx);
    },
    async queue(batch:{messages:{body:{id:string};ack():void}[]},env:JobEnvironment,ctx:unknown){
        return runWithCloudflareRequestContext(new Request('https://fieldwork-research.prasannaramcollege.workers.dev/api/research'),env,ctx,async()=>{
            for(const message of batch.messages){
                message.ack();
                const id=message.body?.id;if(!validJobId(id))continue;
                const time=Date.now();
                try {
                    const runner=env.RESEARCH_RUNNER.get(env.RESEARCH_RUNNER.idFromName(id));
                    const response=await runner.fetch(new Request('https://fieldwork-research.prasannaramcollege.workers.dev/api/internal/research-job',{method:'POST',headers:{'X-Research-Job':id,'X-Research-Time':String(time),'X-Research-Signature':queueSignature(id,time)}}));
                    if(!response.ok)throw Error('Background dispatcher failed.');
                } catch {
                    // The queue context survives a failed research Object. End
                    // polling explicitly; retain every unmetered provider hold.
                    await failInterruptedJob(env.JUDGE_QUOTA,id);
                }
            }
        });
    },
};
